<?php
declare(strict_types=1);
namespace MarketForecast\Tests;
use MarketForecast\Database\Connection;use MarketForecast\Forecast\SnapshotPersistence;use PHPUnit\Framework\TestCase;
final class SnapshotPersistenceTest extends TestCase{public function testSnapshotHashIsStableAndIdempotent():void{$p=tempnam(sys_get_temp_dir(),'snap-');$db=Connection::open($p);$db->exec("create table market_snapshots(id integer primary key autoincrement,experiment_id integer,asset_id integer,information_cutoff text,snapshot_time text,features_json text,source_data_hash text,feature_set_version text,feature_snapshot_hash text,market_data_fingerprint text,market_bar_count integer,unique(experiment_id,asset_id,information_cutoff))");$x=new SnapshotPersistence($db);$bars=[['time'=>'2026-01-01T00:00:00Z','open'=>1,'high'=>2,'low'=>.5,'close'=>1.5,'volume'=>10,'provider'=>'ALPACA']];$a=$x->save(1,1,'2026-01-01T00:00:00Z',['feature_set_version'=>'FEATURE_SET_V1','sma20'=>1],$bars);$b=$x->save(1,1,'2026-01-01T00:00:00Z',['feature_set_version'=>'FEATURE_SET_V1','sma20'=>1],$bars);self::assertGreaterThan(0,$a['id']);self::assertSame($a,$b);self::assertNotSame('',$a['feature_snapshot_hash']);self::assertSame(1,(int)$db->query('select count(*) from market_snapshots')->fetchColumn());@unlink($p);}}
